import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03602Controller {
  @Post('/messages/:messageId/read')
  @HttpCode(200)
  async readMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const messageId = req.params['messageId'];
    if (!/^[0-9]+$/.test(messageId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '메시지 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT message_recipient_id AS "messageRecipientId" FROM message_recipient WHERE message_id = CAST(:messageId AS bigint) AND recipient_id = CAST(:userId AS bigint)',
        { messageId, userId: user.id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'MESSAGE_NOT_FOUND', '본인이 수신한 메시지를 찾을 수 없습니다.');
      }
      // 이미 확인한 메시지는 최초 확인 일시를 유지한다 (가정)
      await db.execute(
        'UPDATE message_recipient SET read_at = COALESCE(read_at, now()), updated_at = now() WHERE message_recipient_id = :id',
        { id: found[0].messageRecipientId },
      );
      const rows = await db.query(
        'SELECT read_at AS "readAt" FROM message_recipient WHERE message_recipient_id = :id',
        { id: found[0].messageRecipientId },
      );
      return { readAt: rows[0].readAt };
    });
  }
}

