import { useState } from 'react';
import { call, Band, Badge, DataTable, DateText, Drawer, Field, Form, LookupSelect, NumberInput, Pairs, RefName, Select, TextInput, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['MAIL', '전자우편'],
  ['CHAT', '메신저'],
  ['NOTE', '쪽지'],
];

export default function FnSfr03602Page({ role, notify }: PageProps) {
  const [sent, setSent] = useState<Row[]>([]);
  const [reads, setReads] = useState<Row[]>([]);
  const [sendOpen, setSendOpen] = useState(false);
  const [readOpen, setReadOpen] = useState(false);
  const [messageType, setMessageType] = useState('MAIL');
  const [subject, setSubject] = useState('');
  const [content, setContent] = useState('');
  const [attachmentRef, setAttachmentRef] = useState('');
  const [recipientIds, setRecipientIds] = useState<number[]>([]);
  const [picked, setPicked] = useState<number | string>('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [readId, setReadId] = useState<number | string>('');

  const openSend = () => {
    setMessageType('MAIL');
    setSubject('');
    setContent('');
    setAttachmentRef('');
    setRecipientIds([]);
    setPicked('');
    setTargetType('');
    setTargetId('');
    setSendOpen(true);
  };

  const openRead = (id: number | string) => {
    setReadId(id);
    setReadOpen(true);
  };

  const addRecipient = () => {
    if (typeof picked !== 'number') return;
    if (recipientIds.includes(picked)) return;
    setRecipientIds([...recipientIds, picked]);
    setPicked('');
  };

  const submitSend = async () => {
    if (!messageType) throw new Error('전달 수단을 선택하세요.');
    if (recipientIds.length === 0) throw new Error('수신 임직원을 한 명 이상 추가하세요.');
    if (!content.trim() && !attachmentRef.trim()) throw new Error('내용 또는 첨부파일 중 하나는 입력하세요.');
    if (!targetType.trim()) throw new Error('연계 대상 업무 항목 유형을 입력하세요.');
    if (targetId === '') throw new Error('연계 대상 업무 항목 ID를 입력하세요.');
    const res = await call('POST', '/messages', role, {
      messageType,
      subject,
      content,
      attachmentRef,
      recipientIds,
      targetType,
      targetId,
    });
    setSent([{ ...res, messageType, subject }, ...sent]);
    setSendOpen(false);
    notify('메시지를 전송했습니다.');
  };

  const submitRead = async () => {
    if (readId === '') throw new Error('메시지 ID를 입력하세요.');
    const res = await call('POST', '/messages/' + readId + '/read', role);
    setReads([{ messageId: readId, readAt: res.readAt }, ...reads]);
    setReadOpen(false);
    notify('수신 확인을 처리했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[
          ['전송한 메시지', sent.length],
          ['수신 확인 처리', reads.length],
        ]} />
      </section>
      <section className="box span-8">
        <h2>전송 내역</h2>
        <Band total={sent.length}>
          <button onClick={openSend}>메시지 전송</button>
          <button onClick={() => openRead('')}>수신 확인</button>
        </Band>
        <DataTable
          rows={sent}
          empty="이 화면에서 전송한 메시지가 없습니다."
          columns={[
            { key: 'messageId', label: '메시지 ID' },
            { key: 'messageType', label: '전달 수단', render: (r) => <Badge value={r.messageType} /> },
            { key: 'subject', label: '제목' },
            { key: 'deliveryResult', label: '전달 성공·실패 여부', render: (r) => <Badge value={r.deliveryResult} /> },
            { key: 'linkStatus', label: '업무 항목 연결 결과' },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>수신 확인</h2>
        <DataTable
          rows={reads}
          empty="수신 확인한 메시지가 없습니다."
          columns={[
            { key: 'messageId', label: '메시지 ID' },
            { key: 'readAt', label: '수신 확인 일시', render: (r) => <DateText value={r.readAt} time /> },
          ]}
        />
      </section>
      {sendOpen && (
        <Drawer title="메시지 전송" onClose={() => setSendOpen(false)}>
          <Form onSubmit={submitSend} submit="전송">
            <Field label="전달 수단" required>
              <Select value={messageType} onChange={setMessageType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="제목">
              <TextInput value={subject} onChange={setSubject} />
            </Field>
            <Field label="공유할 업무 항목 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="첨부파일 연결">
              <TextInput value={attachmentRef} onChange={setAttachmentRef} />
            </Field>
            <Field label="수신 임직원" required wide hint="고른 뒤 추가를 누르세요">
              <LookupSelect table="employee" role={role} value={picked} onChange={setPicked} />
              <button type="button" onClick={addRecipient}>추가</button>
              {recipientIds.map((id) => (
                <div key={id}>
                  <RefName table="employee" role={role} value={id} />
                  <button type="button" onClick={() => setRecipientIds(recipientIds.filter((x) => x !== id))}>삭제</button>
                </div>
              ))}
            </Field>
            <Field label="연계 대상 업무 항목 유형" required>
              <TextInput value={targetType} onChange={setTargetType} />
            </Field>
            <Field label="연계 대상 업무 항목 ID" required>
              <NumberInput value={targetId} onChange={setTargetId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {readOpen && (
        <Drawer title="수신 확인" onClose={() => setReadOpen(false)}>
          <Form onSubmit={submitRead} submit="열람 처리">
            <Field label="메시지 ID" required>
              <NumberInput value={readId} onChange={setReadId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
